(()=>{let token=null,invalid=false;const hadFragment=!!location.hash;try{if(/^#login=[a-f0-9]{64}$/.test(location.hash))token=location.hash.slice(7);else if(hadFragment)invalid=true;history.replaceState(null,'',location.pathname);}catch{token=null;invalid=true;}Object.defineProperty(window,'takeAccountLink',{configurable:true,value:()=>{const result={token,invalid};token=null;return result;}});})();
